import java.util.*;

public class Main {
    static final int INF = 1000000000;
    static int N, M;
    static int[][] capacity = new int[2002][2002];
    static List<Integer>[] graph = new ArrayList[2002];
    static boolean[] visited = new boolean[2002];
    static int[] parent = new int[2002];
    static int[][] directions = { {1,0}, {0,1}, {-1,0}, {0,-1} };

    static int augment(int u) {
        if (u == 1) return INF;
        visited[u] = true;
        for (int v : graph[u]) {
            if (!visited[v] && capacity[u][v] > 0) {
                int flow = augment(v);
                if (flow > 0) {
                    parent[v] = u;
                    return Math.min(flow, capacity[u][v]);
                }
            }
        }
        return 0;
    }

    static int maxFlow() {
        int totalFlow = 0;
        while (true) {
            Arrays.fill(visited, false);
            int flow = augment(0);
            if (flow == 0) break;
            totalFlow += flow;
            int v = 1;
            while (v != 0) {
                int u = parent[v];
                capacity[u][v] -= flow;
                capacity[v][u] += flow;
                v = u;
            }
        }
        return totalFlow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < graph.length; i++) {
            graph[i] = new ArrayList<>();
        }
        int gridSize = sc.nextInt();
        int timeLimit = sc.nextInt();

        for (int i = 0; i < 2 * gridSize * gridSize + 2; ++i) {
            graph[i].clear();
            Arrays.fill(capacity[i], 0);
        }

        String[] sciLabs = new String[gridSize];
        String[] capLabs = new String[gridSize];
        int[][][] vert = new int[gridSize][gridSize][2];
        int malfunctionIndex = -1;

        N = 2;
        for (int i = 0; i < gridSize; ++i) {
            sciLabs[i] = sc.next();
            for (int j = 0; j < gridSize; ++j) {
                char ch = sciLabs[i].charAt(j);
                if (ch >= '1' && ch <= '9') {
                    capacity[0][N] = ch - '0';
                    graph[0].add(N);
                    graph[N].add(0);
                    vert[i][j][0] = N++;
                } else if (ch == 'Z') {
                    malfunctionIndex = 100 * i + j;
                    sciLabs[i] = sciLabs[i].substring(0, j) + 'Y' + sciLabs[i].substring(j + 1);
                }
            }
        }

        M = N;
        for (int i = 0; i < gridSize; ++i) {
            capLabs[i] = sc.next();
            for (int j = 0; j < gridSize; ++j) {
                char ch = capLabs[i].charAt(j);
                if (ch >= '1' && ch <= '9') {
                    capacity[M][1] = ch - '0';
                    graph[M].add(1);
                    vert[i][j][1] = M++;
                }
            }
        }

        int[][] die = new int[gridSize][gridSize];
        for (int i = 0; i < gridSize; ++i)
            Arrays.fill(die[i], timeLimit + 1);
        if (malfunctionIndex != -1) {
            die[malfunctionIndex / 100][malfunctionIndex % 100] = 0;
        }

        Queue<Integer> q = new LinkedList<>();
        if (malfunctionIndex != -1) {
            q.offer(malfunctionIndex);
        }
        while (!q.isEmpty()) {
            int x = q.poll();
            int y = x % 100;
            x /= 100;
            for (int[] d : directions) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 0 && nx < gridSize && ny >= 0 && ny < gridSize && sciLabs[nx].charAt(ny) != 'Y' && die[nx][ny] > die[x][y] + 1) {
                    die[nx][ny] = die[x][y] + 1;
                    q.offer(100 * nx + ny);
                }
            }
        }

        int[][] reach = new int[gridSize][gridSize];
        for (int i = 0; i < gridSize; ++i)
            Arrays.fill(reach[i], timeLimit + 1);

        for (int i = 0; i < gridSize; ++i) {
            for (int j = 0; j < gridSize; ++j) {
                if (sciLabs[i].charAt(j) >= '1' && sciLabs[i].charAt(j) <= '9') {
                    for (int x = 0; x < gridSize; ++x)
                        Arrays.fill(reach[x], timeLimit + 1);
                    reach[i][j] = 0;
                    if (capLabs[i].charAt(j) >= '1' && capLabs[i].charAt(j) <= '9') {
                        capacity[vert[i][j][0]][vert[i][j][1]] = INF;
                        graph[vert[i][j][0]].add(vert[i][j][1]);
                        graph[vert[i][j][1]].add(vert[i][j][0]);
                    }
                    Queue<Integer> q2 = new LinkedList<>();
                    q2.offer(100 * i + j);
                    while (!q2.isEmpty()) {
                        int x = q2.poll();
                        int y = x % 100;
                        x /= 100;
                        for (int[] d : directions) {
                            int nx = x + d[0];
                            int ny = y + d[1];
                            if (nx >= 0 && nx < gridSize && ny >= 0 && ny < gridSize && sciLabs[nx].charAt(ny) != 'Y' && reach[nx][ny] > reach[x][y] + 1) {
                                if (capLabs[nx].charAt(ny) >= '1' && capLabs[nx].charAt(ny) <= '9') {
                                    if (reach[x][y] + 1 <= die[nx][ny]) {
                                        capacity[vert[i][j][0]][vert[nx][ny][1]] = INF;
                                        graph[vert[i][j][0]].add(vert[nx][ny][1]);
                                        graph[vert[nx][ny][1]].add(vert[i][j][0]);
                                    }
                                }
                                if (reach[x][y] + 1 < die[nx][ny]) {
                                    reach[nx][ny] = reach[x][y] + 1;
                                    q2.offer(100 * nx + ny);
                                }
                            }
                        }
                    }
                }
            }
        }

        System.out.println(maxFlow());
        sc.close();
    }
}
